<?php
namespace App\Livewire\Admin\CallCentre;use App\Models\CallCenterCall;use Livewire\Component;
class Show extends Component{public CallCenterCall $call;public string $status='';public string $call_notes='';public array $call_checklist_completed=[];public function mount():void{$this->authorizeCall();$this->call->load(['lead','assignedUser']);$this->status=$this->call->status;$this->call_notes=$this->call->call_notes??'';$this->call_checklist_completed=$this->call->call_checklist_completed??[];}private function authorizeCall():void{$u=auth()->user();abort_unless($u&&($u->isAdmin()||($u->isCallCenter()&&$this->call->assigned_call_center_user===$u->id)),403);}public function recordAttempt(string $result):void{$this->authorizeCall();abort_unless(in_array($result,[CallCenterCall::STATUS_CALLED,CallCenterCall::STATUS_NOT_ANSWERED],true),422);$this->call->update(['status'=>$result,'call_attempts'=>$this->call->call_attempts+1,'last_call_attempt'=>now()]);$this->status=$result;$this->call->refresh();}public function save():void{$this->authorizeCall();$d=$this->validate(['status'=>['required','in:'.implode(',',array_keys(CallCenterCall::getStatuses()))],'call_notes'=>['nullable','string','max:10000'],'call_checklist_completed'=>['array']]);$this->call->update($d);$this->call->refresh();session()->flash('success','Call record updated.');}public function render(){return view('livewire.admin.call-centre.show',['statuses'=>CallCenterCall::getStatuses()])->layout('components.layouts.admin',['title'=>'Call '.$this->call->id]);}}
